/* Own campaign crew notes stay in the match room until its result is confirmed. */
(()=>{'use strict';
const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),T=(en,ko)=>window.UKI18n?.language==='en'?en:ko,L=(en,ko)=>`<span data-i18n-en="${E(en)}" data-i18n-ko="${E(ko)}">${E(T(en,ko))}</span>`,copy=v=>JSON.parse(JSON.stringify(v));
const states=new Map(),recordFields=['xp','kills','xpHistory','injuries','effects','status','pendingEscape'],combatStates=[['Ready','Ready','전투 가능'],['Pinned','Pinned','제압됨'],['Seriously Injured','Seriously injured','중상'],['Out of Action','Out of Action','전투 불능']];
let active=null,restoring=false,opening=0,routeEpoch=0,lastRoute='',restoreError='';
const navigationKey='underhive-campaign-play-navigation';
const justicarModels=new Set(['magistrate','executioner','bailiff'].map(name=>'official-001-fighter-justicar-court-delegation-'+name));
const isJusticar=f=>!!f&&[f.fighterTypeId,f.catalogTypeId,f.presetId,f.typeId].some(id=>justicarModels.has(id));
const actor=()=>window.AccountParity?.account?.id||'',units=g=>[...(g?.fighters||[]),...(g?.vehicles||[])],cid=c=>c.remoteCampaignId||c.id;
const routeStamp=()=>JSON.stringify([actor(),data.view,data.selectedGang,data.selectedCampaign]);
function observeRoute(){const next=routeStamp();if(next!==lastRoute){lastRoute=next;routeEpoch++;}}
function entryGuard(){observeRoute();const epoch=routeEpoch,attempt=++opening;return ()=>{observeRoute();return attempt===opening&&epoch===routeEpoch;};}
function campaignFor(ctx){return data.campaigns.find(c=>c.id===ctx.localCampaignId)||data.campaigns.find(c=>cid(c)===ctx.campaignId);}
function originalFor(ctx){const g=data.gangs.find(g=>g.id===ctx.gangId),c=campaignFor(ctx);return g&&c&&window.MMCampaignOwnership?.owns(g)&&window.MMCampaignOwnership?.canManage(c,g)?g:null;}
function valid(ctx){return !!ctx&&actor()===ctx.actor&&!!originalFor(ctx);}
function current(ctx){return active===ctx&&valid(ctx)&&window.MMPlayMode?.campaignContext?.()===ctx.adapter;}
function rememberNavigation(ctx){try{sessionStorage.setItem(navigationKey,JSON.stringify({actor:ctx.actor,campaignId:ctx.campaignId,localCampaignId:ctx.localCampaignId,gangId:ctx.gangId,roomId:ctx.room.id}));}catch{}}
function savedNavigation(g){let saved;try{saved=JSON.parse(sessionStorage.getItem(navigationKey)||'null');}catch{return null;}if(!g||!saved||saved.actor!==actor()||saved.gangId!==g.id||typeof saved.roomId!=='string'||!saved.roomId||saved.roomId.length>500)return null;const c=data.campaigns.find(c=>c.id===saved.localCampaignId&&cid(c)===saved.campaignId)||data.campaigns.find(c=>cid(c)===saved.campaignId);return c&&window.MMCampaignOwnership?.owns(g)&&window.MMCampaignOwnership?.canManage(c,g)?{saved,c}:null;}
function canResume(g=gang()){return !!g&&!!((active?.gangId===g.id&&valid(active))||savedNavigation(g));}
async function resume(g=gang()){if(!g)return false;const ctx=active?.gangId===g.id&&valid(active)?active:null,target=ctx?{c:campaignFor(ctx),saved:{actor:ctx.actor,gangId:ctx.gangId,roomId:ctx.room.id}}:savedNavigation(g);return target?open(target.c,{id:target.saved.roomId},{userId:target.saved.actor,sourceGangId:target.saved.gangId},ctx?.options||{}):false;}
function viewGang(){opening++;const ctx=active?.gangId===data.selectedGang&&valid(active)?active:null;if(ctx){if(ctx.pending)persistPending(ctx);rememberNavigation(ctx);data.selectedGang=ctx.gangId;}data.view=gang()?'gang':'gangs';data.tab='fighters';window.MMPlayMode.close({skipCampaign:true});save();return true;}
function self(ctx){return ctx.room?.participants?.find(p=>p.userId===ctx.actor);}
function crew(ctx){const prep=self(ctx)?.preparation;return [...new Set([...(prep?.fighterIds||[]),...(prep?.reinforcements||[]).map(row=>row.fighterId)].filter(id=>typeof id==='string'))];}
function crewRow(ctx,id){const prep=self(ctx)?.preparation;return (prep?.crew||[]).find(row=>row.fighterId===id)||(prep?.reinforcements||[]).find(row=>row.fighterId===id);}
function pendingKey(ctx){return 'underhive-campaign-play-pending:'+JSON.stringify([ctx.actor,ctx.campaignId,ctx.room.id]);}
function persistPending(ctx){try{if(ctx.pending)sessionStorage.setItem(pendingKey(ctx),JSON.stringify({actor:ctx.actor,campaignId:ctx.campaignId,roomId:ctx.room.id,gangId:ctx.gangId,operation:ctx.pending}));else sessionStorage.removeItem(pendingKey(ctx));ctx.storageWarning='';}catch{ctx.storageWarning=T('This browser could not keep a local recovery copy. Keep this page open and retry saving.','브라우저에 복구용 임시 사본을 저장하지 못했습니다. 이 화면을 유지한 채 저장을 다시 시도하세요.');}}
function recoverPending(ctx){if(ctx.pending)return;let value;try{const raw=sessionStorage.getItem(pendingKey(ctx));if(!raw||raw.length>2000000)return;value=JSON.parse(raw);}catch{return;}const operation=value?.operation;if(value?.actor!==ctx.actor||value.campaignId!==ctx.campaignId||value.roomId!==ctx.room.id||value.gangId!==ctx.gangId||operation?.action!=='battle-update'||typeof operation.operationKey!=='string'||operation.operationKey.length>160||!Array.isArray(operation.units)||!operation.units.length||operation.units.some(unit=>!crew(ctx).includes(unit.fighterId)))return;ctx.pending=operation;for(const unit of operation.units)ctx.draftUnits.set(unit.fighterId,copy(unit));ctx.error=T('Recovered unsaved temporary records. Retry to save them to the match room.','저장되지 않은 임시 기록을 복원했습니다. 다시 시도해 매칭룸에 저장하세요.');}
function normalized(f){return {xp:Number(f?.xp)||0,kills:Number(f?.kills)||0,xpHistory:copy(f?.xpHistory||[]),injuries:copy(f?.injuries||[]),effects:copy(f?.effects||[]),status:f?.status||'Active',pendingEscape:!!f?.pendingEscape};}
function baseUnit(ctx,id){return self(ctx)?.battleRecord?.base?.find(unit=>unit.fighterId===id)?.record||normalized(units(originalFor(ctx)).find(f=>f.id===id));}
function storedUnit(ctx,id){return ctx.draftUnits.get(id)||self(ctx)?.battleRecord?.units?.find(unit=>unit.fighterId===id);}
function previewGang(ctx){const g=copy(originalFor(ctx));if(!g)return null;for(const f of g.vehicles||[])f.isVehicle=true;for(const f of units(g)){const record=storedUnit(ctx,f.id)?.record;if(record)for(const field of recordFields)f[field]=copy(record[field]);if(isJusticar(f)){f.loadouts=[];continue;}const selected=crewRow(ctx,f.id);if(selected&&typeof selected.loadoutId==='string')for(const loadout of f.loadouts||[])loadout.active=loadout.id===selected.loadoutId;}return g;}
function paint(ctx){if(!current(ctx))return;const focused=document.activeElement,inside=focused?.closest?.('.pm-page');if(inside){if(focused.dataset.campaignPlayAction)ctx.focusAnchor={action:focused.dataset.campaignPlayAction,fighter:focused.dataset.campaignPlayFighter};else if(focused.dataset.campaignPlayCombat)ctx.focusAnchor={combat:focused.dataset.campaignPlayCombat};else if(focused.dataset.campaignPlayDeployed)ctx.focusAnchor={deployed:focused.dataset.campaignPlayDeployed};}window.MMPlayMode.refresh();if(document.querySelector('.modal-bg,.mmrr-overlay'))return;const anchor=ctx.focusAnchor;let target=anchor?.deployed?[...document.querySelectorAll('[data-campaign-play-deployed]')].find(n=>n.dataset.campaignPlayDeployed===anchor.deployed):anchor?.combat?[...document.querySelectorAll('[data-campaign-play-combat]')].find(n=>n.dataset.campaignPlayCombat===anchor.combat):anchor?.action?[...document.querySelectorAll('[data-campaign-play-action]')].find(n=>n.dataset.campaignPlayAction===anchor.action&&(!anchor.fighter||n.dataset.campaignPlayFighter===anchor.fighter)):null;if(target?.disabled)target=null;if(!target&&ctx.error)target=document.querySelector('[data-campaign-play-action=retry],[data-campaign-play-action=correction]');target?.focus({preventScroll:true});}
function editable(ctx){return valid(ctx)&&ctx.room?.status==='battle'&&!ctx.room.canCancel&&!!self(ctx)?.battleRecord&&!ctx.busy&&!ctx.pending;}
function baseline(){return {accountId:actor(),collections:JSON.stringify({gangs:data.gangs,campaigns:data.campaigns,customAssets:data.customAssets,skirmishes:data.skirmishes})};}
function absorb(result,base){if(result?.document&&Number.isSafeInteger(result.document.revision)&&result.document.revision>window.AccountParity.revision)window.AccountParity.acceptAutomation?.(result,base);}
async function request(ctx,method='GET',body){if(!valid(ctx))throw Error(T('Your account or campaign changed. Reopen the match room.','계정이나 캠페인이 변경되었습니다. 매칭룸을 다시 여세요.'));let timeout;try{return await Promise.race([window.AccountParity.api('/campaigns/'+encodeURIComponent(ctx.campaignId)+'/lobby/'+encodeURIComponent(ctx.room.id)+(method==='GET'?'?documentRevision='+window.AccountParity.revision:''),method==='GET'?undefined:{method,headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),new Promise((_,reject)=>{timeout=setTimeout(()=>reject(Error(T('The room took too long to respond. Your draft is kept. Retry to check its saved state.','서버 응답이 지연됩니다. 임시 기록을 유지했습니다. 다시 시도해 저장 상태를 확인하세요.'))),20000);})]);}finally{clearTimeout(timeout);}}
function accept(ctx,result){if(!result?.room)return;ctx.room=result.room;ctx.updatedAt=self(ctx)?.battleRecord?.updatedAt||'';}
function bodyFor(ctx,action,fields={}){return {action,revision:ctx.room.revision,participantRevision:self(ctx)?.revision,operationKey:'battle-play:'+crypto.randomUUID(),...fields};}
async function savePending(ctx){
 if(!ctx.pending)return true;if(ctx.saving)return ctx.saving;if(!valid(ctx))return false;
 ctx.busy=true;ctx.error='';paint(ctx);const pending=ctx.pending;
 const operation=(async()=>{try{await window.AccountParity.ensureSynced?.();if(!valid(ctx))return false;const base=baseline(),result=await request(ctx,'POST',pending);if(!valid(ctx))return false;accept(ctx,result);if(ctx.pending===pending)ctx.pending=null;persistPending(ctx);ctx.draftUnits.clear();ctx.error='';absorb(result,base);return true;}catch(error){ctx.error=error.message||String(error);if(error.status===409){try{const latest=await request(ctx);if(valid(ctx))accept(ctx,latest);}catch{}}return false;}finally{ctx.busy=false;ctx.saving=null;paint(ctx);}})();ctx.saving=operation;return operation;
}
function queueUnit(ctx,id,next){if(!editable(ctx)||!crew(ctx).includes(id))return false;ctx.draftUnits.set(id,copy(next));ctx.pending=bodyFor(ctx,'battle-update',{units:[copy(next)]});persistPending(ctx);queueMicrotask(()=>savePending(ctx));return true;}
function applyMutation(ctx,id,mutate){
 if(!editable(ctx))return false;const g=previewGang(ctx),f=units(g).find(f=>f.id===id);if(!f)return false;const before=baseUnit(ctx,id),row={fighterId:id,xpEarned:Number(f.xp||0)-Number(before.xp||0),injuries:[]};mutate(f,g,row);
 const next={fighterId:id,record:normalized(f),combat:copy(storedUnit(ctx,id)?.combat||{status:'Ready'})};return queueUnit(ctx,id,next);
}
function manualXp(ctx,id){const g=previewGang(ctx),f=units(g).find(f=>f.id===id);if(!f)return;formModal(T('Record temporary XP','임시 XP 기록'),`<p class="wide">${L('This change is applied to the roster only when the match result is confirmed.','이 변화는 경기 종료를 확정할 때 원본 로스터에 반영됩니다.')}</p><label>${L('XP change','XP 변화량')}<input type="number" name="amount" step="1" value="0" required></label><label class="wide">${L('Reason','사유')}<input name="reason" maxlength="500"></label>`,values=>{const amount=Number(values.amount);if(!Number.isSafeInteger(amount)||Number(f.xp||0)+amount<0){alert(T('Enter a whole XP change that keeps total XP at zero or more.','XP 합계가 0 이상이 되도록 정수 변화량을 입력하세요.'));return false;}return applyMutation(ctx,id,(unit)=>{unit.xp=Number(unit.xp||0)+amount;(unit.xpHistory??=[]).unshift({id:crypto.randomUUID(),at:new Date().toISOString(),amount,reason:String(values.reason||T('Manual battle XP','전투 XP 직접 기록')),manual:true,sessionId:ctx.room.sessionId});});},T('Save temporary record','임시 기록 저장'));}
function manualInjury(ctx,id){formModal(T('Record an injury note','부상 메모 기록'),`<p class="wide">${L('Record the agreed injury. This note does not infer rule effects or change characteristics.','합의한 부상 내용을 기록하세요. 이 메모는 룰 효과나 능력치를 자동으로 적용하지 않습니다.')}</p><label class="wide">${L('Injury note','부상 메모')}<textarea name="note" maxlength="2000" required></textarea></label>`,values=>{const note=String(values.note||'').trim();if(!note)return false;return applyMutation(ctx,id,unit=>{(unit.injuries??=[]).push({id:crypto.randomUUID(),name:T('Manual injury','직접 기록한 부상'),manual:true,is_custom:true,description:note,acquiredAt:new Date().toISOString(),sessionId:ctx.room.sessionId});});},T('Save temporary record','임시 기록 저장'));}
function delegationTable(){return `<table class="wide"><caption>${L('Alliance delegation · D6 lasting injuries','동맹 파견대 · D6 지속 부상')}</caption><thead><tr><th scope="col">D6</th><th scope="col">${L('Result','결과')}</th></tr></thead><tbody><tr><th scope="row">1–2</th><td>${L('Out Cold · no lasting effect','기절 · 지속 효과 없음')}</td></tr><tr><th scope="row">3–5</th><td>${L('Grievous Wound · Recovery','중상 · 회복 중')}</td></tr><tr><th scope="row">6</th><td>${L('Critical Injury · delete the model and its equipment','치명상 · 모델과 보유 장비 삭제')}</td></tr></tbody></table>`;}
function delegationInjury(ctx,id){
 if(!editable(ctx)||!crew(ctx).includes(id))return false;
 const f=units(previewGang(ctx)).find(unit=>unit.id===id);if(!isJusticar(f))return false;
 const proof=self(ctx)?.battleRecord?.delegationRolls?.find(proof=>proof.fighterId===id);
 const note=proof?`<p class="wide" role="status"><strong>${L('Saved roll','저장된 결과')}: ${proof.roll} · ${E(T(proof.injury.name,proof.injury.name_ko||proof.injury.name))}</strong></p>`:`<p class="wide">${L('Roll once for this fighter in this match. The saved result is applied when both players confirm the match result.','이 경기에서 이 파견 모델의 D6을 한 번 굴립니다. 저장된 결과는 양쪽이 경기 결과를 확정할 때 반영됩니다.')}</p>`;
 formModal(T('Justicar delegation injury','저스티카 파견대 부상'),delegationTable()+note+`<p class="wide">${L('Palanite Enforcers: the first deletion from a lasting injury receives an identical replacement.','팔라나이트 인포서: 지속 부상으로 처음 삭제된 파견 모델은 동일한 대체 모델로 교체됩니다.')}</p>`,async()=>{
  if(proof)return true;if(!editable(ctx))throw Error(T('The match changed. Reopen the saved record.','경기 상태가 바뀌었습니다. 저장된 기록을 다시 여세요.'));
  ctx.delegationOperations??={};const operation=ctx.delegationOperations[id]??=bodyFor(ctx,'battle-delegation-injury',{fighterId:id});ctx.busy=true;ctx.error='';paint(ctx);
  try{await window.AccountParity.ensureSynced?.();if(!valid(ctx))return false;const base=baseline(),result=await request(ctx,'POST',operation);if(!valid(ctx))return false;accept(ctx,result);delete ctx.delegationOperations[id];ctx.draftUnits.clear();absorb(result,base);return true;}
  catch(error){ctx.error=error.message||String(error);if(error.status===409){try{const result=await request(ctx);if(valid(ctx)){accept(ctx,result);delete ctx.delegationOperations[id];if(self(ctx)?.battleRecord?.delegationRolls?.some(proof=>proof.fighterId===id))return true;}}catch{}}throw error;}finally{ctx.busy=false;paint(ctx);}
 },proof?T('Close','닫기'):T('Roll D6 and save','D6 굴려 저장'));
 return true;
}
function editUnit(ctx,id,kind){
 if(!editable(ctx)||!crew(ctx).includes(id))return;const g=previewGang(ctx),f=units(g).find(f=>f.id===id);if(!f)return;
 if(isJusticar(f)){if(kind==='injury')delegationInjury(ctx,id);return;}
 const isN26=String(g.edition).toUpperCase()==='N26',rules=window.RULES_DATA||{},hasXp=isN26&&(rules.coreRules||[]).some(r=>r.source_verified&&r.rule_data?.events&&String(r.edition_slug||r.edition).toUpperCase()==='N26'),hasInjury=isN26&&(f.isVehicle?rules.effects:rules.injuries||[]).some(r=>r.source_verified&&r.rule_data?.model_type===(f.isVehicle?'Vehicle':'Fighter')&&r.rule_data?.d66_min&&String(r.edition_slug||r.edition).toUpperCase()==='N26');
 if(kind==='xp'&&!hasXp){manualXp(ctx,id);return;}if(kind==='injury'&&!hasInjury){manualInjury(ctx,id);return;}
 const context={gang:g,sessionId:ctx.room.sessionId,commit:mutate=>applyMutation(ctx,id,mutate)};window.MMVerifiedRules?.[kind]?.(f,context);
 const modal=document.querySelector('#modal-form')?.closest('.modal');if(modal){const note=document.createElement('p');note.className='wide pm-battle-modal-note';note.textContent=T('Temporary match record. Applied to your roster only when the match result is confirmed.','경기 중 임시 기록입니다. 경기 종료를 확정할 때 원본 로스터에 반영됩니다.');document.querySelector('#modal-form').prepend(note);const submit=modal.querySelector('#modal-submit');if(submit)submit.textContent=T('Save temporary record','임시 기록 저장');}
}
async function refresh(ctx){if(!valid(ctx)||ctx.busy||ctx.pending)return false;ctx.busy=true;ctx.error='';paint(ctx);try{await window.AccountParity.ensureSynced?.();if(!valid(ctx))return false;const base=baseline(),result=await request(ctx);if(!valid(ctx))return false;accept(ctx,result);ctx.draftUnits.clear();absorb(result,base);return true;}catch(error){ctx.error=error.message||String(error);return false;}finally{ctx.busy=false;paint(ctx);}}
async function requestCorrection(ctx){if(!valid(ctx)||ctx.busy||ctx.room.status!=='result_pending')return;ctx.busy=true;ctx.error='';paint(ctx);try{const result=await request(ctx,'POST',bodyFor(ctx,'dispute-result'));accept(ctx,result);if(ctx.pending){ctx.pending={...ctx.pending,revision:ctx.room.revision,participantRevision:self(ctx)?.revision,operationKey:'battle-play:'+crypto.randomUUID()};persistPending(ctx);}ctx.busy=false;if(ctx.pending)await savePending(ctx);}catch(error){ctx.error=error.message||String(error);}finally{ctx.busy=false;paint(ctx);}}
async function rebase(ctx){if(!valid(ctx)||ctx.busy||ctx.room.status!=='battle')return false;ctx.busy=true;ctx.error='';paint(ctx);try{await window.AccountParity.ensureSynced?.();if(!valid(ctx))return false;ctx.rebaseOperation??=bodyFor(ctx,'battle-rebase',{confirm:true});const result=await request(ctx,'POST',ctx.rebaseOperation);if(!valid(ctx))return false;accept(ctx,result);ctx.rebaseOperation=null;ctx.pending=null;persistPending(ctx);ctx.draftUnits.clear();return true;}catch(error){ctx.error=error.message||String(error);if(error.status===409){ctx.rebaseOperation=null;try{const result=await request(ctx);if(valid(ctx))accept(ctx,result);}catch{}}return false;}finally{ctx.busy=false;paint(ctx);}}
function terminalPending(ctx){return !!ctx.pending&&(ctx.room.canCancel||['completed','cancelled','declined'].includes(ctx.room.status));}
async function keepAndReturn(ctx){if(!valid(ctx)||ctx.busy||!terminalPending(ctx))return false;try{sessionStorage.setItem(pendingKey(ctx)+':archived',JSON.stringify({actor:ctx.actor,campaignId:ctx.campaignId,roomId:ctx.room.id,gangId:ctx.gangId,operation:ctx.pending,archivedAt:new Date().toISOString()}));sessionStorage.removeItem(pendingKey(ctx));}catch{ctx.error=T('The recovery copy could not be stored. Keep this page open so the unconfirmed records are not lost.','복구용 기록을 보관하지 못했습니다. 미반영 기록이 사라지지 않도록 이 화면을 유지하세요.');paint(ctx);return false;}ctx.pending=null;ctx.draftUnits.clear();ctx.error='';return returnToRoom(ctx);}
async function returnToRoom(ctx){if(!current(ctx))return false;if(ctx.saving){if(!await ctx.saving)return false;}else if(ctx.busy)return false;if(ctx.pending&&!await savePending(ctx))return false;if(!current(ctx))return false;opening++;try{sessionStorage.removeItem(navigationKey);}catch{}active=null;window.MMPlayMode.close({skipCampaign:true});if(ctx.options.onReturn)ctx.options.onReturn(ctx.room);else if(!window.MMCommandReference?.returnToCampaignRoom?.(campaignFor(ctx)?.id||ctx.localCampaignId,ctx.room.id)){const c=campaignFor(ctx);if(c){data.selectedCampaign=c.id;data.view='campaign';data.campaignTab='overview';render();}}return true;}
// Keep exceptional save recovery visible without the removed instructional panel.
function headerMarkup(ctx){return `${ctx.error?`<div class="pm-battle-error" role="alert"><p>${E(ctx.error)}</p>${terminalPending(ctx)?`<p>${L('The match is complete or its conditions changed. These unsaved changes cannot be applied to the original roster.','이미 끝났거나 진행 조건이 바뀐 경기입니다. 이 미저장 변경사항은 원본 로스터에 반영되지 않습니다.')}</p><button type="button" class="btn" data-campaign-play-action="keep-return">${L('Return without applying these records','기록을 반영하지 않고 방으로')}</button>`:ctx.pending&&ctx.room.status==='result_pending'?`<button type="button" class="btn" data-campaign-play-action="correction">${L('Request result correction','결과 수정 요청')}</button>`:ctx.pending?`<button type="button" class="btn" data-campaign-play-action="retry">${L('Retry saving','저장 다시 시도')}</button>`:''}${ctx.room.status==='battle'?`<button type="button" class="btn" data-campaign-play-action="rebase" ${ctx.busy?'disabled':''}>${L('Restart from the current roster','현재 로스터로 임시 기록 다시 시작')}</button>`:''}</div>`:''}${ctx.pending&&ctx.storageWarning?`<p class="pm-battle-storage-warning" role="status">${E(ctx.storageWarning)}</p>`:''}`;}
function unitMarkup(ctx,f){const base=baseUnit(ctx,f.id),draft=storedUnit(ctx,f.id),record=draft?.record||normalized(f),gain=Number(record.xp||0)-Number(base.xp||0),newInjuries=(record.injuries||[]).filter(row=>!(base.injuries||[]).some(old=>old.id===row.id)),status=draft?.combat?.status||'Ready',disabled=!editable(ctx),selected=crewRow(ctx,f.id),reserve=!(self(ctx)?.preparation?.fighterIds||[]).includes(f.id),loadout=selected&&(f.loadouts||[]).find(row=>row.id===selected.loadoutId),delegation=isJusticar(f),rolled=!!self(ctx)?.battleRecord?.delegationRolls?.some(row=>row.fighterId===f.id),deployed=draft?.combat?.deployed===true||status!=='Ready'||JSON.stringify(record)!==JSON.stringify(base);return `<section class="pm-battle-unit" data-campaign-play-unit="${E(f.id)}"><div class="pm-battle-unit-heading"><h3>${L('This match · temporary record','이번 경기 · 임시 기록')}</h3><span>${E((gain>0?'+':'')+gain)} XP</span></div>${selected?`<p><span class="chip" data-campaign-play-crew-kind="${reserve?'reinforcement':'starting'}">${reserve?L('Reinforcement roster','증원 명단'):L('Starting crew','시작 크루')}</span>${loadout?.name?` · <span data-user-text>${E(loadout.name)}</span>`:''}</p>`:''}<p>${L('Starting XP','시작 XP')} ${E(base.xp)} → ${L('Preview','반영 예정')} ${E(record.xp)} · ${L('New injuries','새 부상')} ${newInjuries.length}</p>${reserve?`<label class="checkline" style="min-height:44px"><input type="checkbox" data-campaign-play-deployed="${E(f.id)}" ${deployed?'checked':''} ${disabled||status!=='Ready'||newInjuries.length?'disabled':''}><span>${L('This reserve entered the battlefield','이 증원이 실제 전장에 투입됨')}</span></label>`:''}<label class="pm-battle-combat">${L('Battle status','전투 중 상태')}<select data-campaign-play-combat="${E(f.id)}" ${disabled?'disabled':''}>${combatStates.map(([value,en,ko])=>`<option value="${value}" ${value===status?'selected':''}>${E(T(en,ko))}</option>`).join('')}</select></label><div class="pm-battle-unit-actions">${delegation?'':`<button type="button" class="btn" data-campaign-play-action="xp" data-campaign-play-fighter="${E(f.id)}" ${disabled?'disabled':''}>${L('Record XP','경험치 기록')}</button>`}<button type="button" class="btn" data-campaign-play-action="injury" data-campaign-play-fighter="${E(f.id)}" ${disabled?'disabled':''}>${delegation?L('D6 delegation injury','D6 파견대 부상'):L('Record lasting injury','지속 부상 기록')}</button><button type="button" class="btn" data-campaign-play-action="reset" data-campaign-play-fighter="${E(f.id)}" ${disabled||rolled?'disabled':''}>${L('Reset this record','이 유닛 기록 초기화')}</button></div>${newInjuries.length?`<ul class="pm-battle-injury-list">${newInjuries.map(row=>`<li data-user-text>${row.delegationRoll?'D6 '+E(row.delegationRoll)+' · ':''}${E(window.UKI18n?.language==='en'?row.name:row.name_ko||row.name)}</li>`).join('')}</ul>`:''}</section>`;}
async function open(c,room,participant,options={}){
 const account=actor();if(!account||!c||!room||participant?.userId!==account)return false;
 const campaignId=cid(c),g=(window.MMCampaignOwnership?.ownGangs(c)||[]).find(g=>g.id===participant.sourceGangId)||window.MMCampaignOwnership?.resolveOwn?.(participant.sourceGangId||participant.gangId);if(!g||!window.MMCampaignOwnership?.owns(g)||!window.MMCampaignOwnership?.canManage(c,g))return false;
 const entering=entryGuard();restoreError='';const key=account+':'+campaignId+':'+room.id;let ctx=states.get(key);if(!ctx){ctx={actor:account,campaignId,localCampaignId:c.id,gangId:g.id,room:copy(room),options,draftUnits:new Map(),pending:null,saving:null,busy:false,error:''};states.set(key,ctx);}else{if(ctx.saving)await ctx.saving;if(!valid(ctx)||!entering())return false;ctx.options=options;ctx.room=copy(room);}
 await window.AccountParity.ensureSynced?.();if(!valid(ctx)||!entering())return false;const base=baseline(),result=await request(ctx);if(!valid(ctx)||!entering())return false;accept(ctx,result);if(self(ctx)?.sourceGangId!==ctx.gangId)throw Error(T('The gang in this room changed. Reopen it from the campaign lobby.','이 방의 내 갱이 변경되었습니다. 캠페인 로비에서 다시 입장하세요.'));absorb(result,base);if(!entering())return false;
 if(ctx.room.status==='battle'&&!self(ctx)?.battleRecord){const initialized=await request(ctx,'POST',bodyFor(ctx,'battle-initialize'));if(!valid(ctx)||!entering())return false;accept(ctx,initialized);}
 recoverPending(ctx);
 if(!['battle','result_pending','completed'].includes(ctx.room.status))throw Error(T('Start the match before opening its play roster.','경기를 시작한 뒤 플레이 로스터를 여세요.'));
 ctx.adapter={isValid:()=>valid(ctx),busy:()=>ctx.busy,unitIds:()=>crew(ctx),viewGang:()=>previewGang(ctx),unitMarkup:f=>unitMarkup(ctx,f),headerMarkup:()=>headerMarkup(ctx),onClose:()=>returnToRoom(ctx)};active=ctx;data.selectedGang=ctx.gangId;data.view='campaign-play';rememberNavigation(ctx);save();return window.MMPlayMode.open(originalFor(ctx),{campaign:ctx.adapter});
}
window.addEventListener('click',event=>{const button=event.target.closest?.('[data-campaign-play-action]');if(!button||button.disabled)return;const action=button.dataset.campaignPlayAction;if(action==='resume'){event.preventDefault();event.stopImmediatePropagation();resume().catch(error=>window.MMCampaignAutomation?.notify?.(error.message||String(error),true));return;}if(action==='view-gang'&&data.view==='campaign-play'){event.preventDefault();event.stopImmediatePropagation();viewGang();return;}if(!active||!current(active))return;event.preventDefault();event.stopImmediatePropagation();const ctx=active;if(['xp','injury'].includes(action))editUnit(ctx,button.dataset.campaignPlayFighter,action);else if(action==='retry')savePending(ctx);else if(action==='refresh')refresh(ctx);else if(action==='return')returnToRoom(ctx);else if(action==='correction')requestCorrection(ctx);else if(action==='rebase')rebase(ctx);else if(action==='keep-return')keepAndReturn(ctx);else if(action==='reset'){const id=button.dataset.campaignPlayFighter;queueUnit(ctx,id,{fighterId:id,record:copy(baseUnit(ctx,id)),combat:{status:'Ready'}});}},true);
document.addEventListener('toggle',event=>{if(active&&current(active)&&event.target.matches?.('.pm-battle-recovery'))active.recoveryOpen=event.target.open;},true);
window.addEventListener('change',event=>{const field=event.target.closest?.('[data-campaign-play-combat],[data-campaign-play-deployed]');if(!field||field.disabled||!active||!current(active))return;const ctx=active,id=field.dataset.campaignPlayCombat||field.dataset.campaignPlayDeployed,next=copy(storedUnit(ctx,id)||{fighterId:id,record:normalized(units(previewGang(ctx)).find(f=>f.id===id)),combat:{status:'Ready'}});if(field.dataset.campaignPlayDeployed)next.combat={...(next.combat||{status:'Ready'}),deployed:field.checked};else{if(!combatStates.some(([value])=>value===field.value))return;next.combat={...(next.combat||{}),status:field.value,...(!(self(ctx)?.preparation?.fighterIds||[]).includes(id)&&field.value!=='Ready'?{deployed:true}:{})};}queueUnit(ctx,id,next);},true);
async function restore(){if(active&&!valid(active))active=null;if(current(active)||restoring||!window.AccountParity?.ready||data.view!=='campaign-play')return;const target=savedNavigation(gang());if(!target)return;const {saved,c}=target;observeRoute();const epoch=routeEpoch,attempt=opening+1;restoring=true;try{await open(c,{id:saved.roomId},{userId:saved.actor,sourceGangId:saved.gangId},active?.options||{});}catch(error){observeRoute();if(epoch!==routeEpoch||attempt!==opening||data.view!=='campaign-play'||actor()!==saved.actor||data.selectedGang!==saved.gangId)return;restoreError=error.message||String(error);try{sessionStorage.removeItem(navigationKey);}catch{}window.MMCampaignAutomation?.notify?.(restoreError,true);render();}finally{restoring=false;}}
const beforeRender=render;render=function(...args){observeRoute();const result=beforeRender.apply(this,args);observeRoute();queueMicrotask(restore);return result;};
window.MMJusticarInjuries={open(f,context={}){
 if(active&&current(active)&&context.sessionId===active.room.sessionId&&crew(active).includes(f.id))return delegationInjury(active,f.id);
 const g=context.gang||gang(),can=canResume(g);
 formModal(T('Justicar delegation injury','저스티카 파견대 부상'),delegationTable()+`<p class="wide">${L('Open the campaign match’s play roster to roll and save this injury. Death, equipment deletion and Strong Alliance replacement are applied together after both players confirm the result.','캠페인 경기의 플레이 로스터에서 부상을 굴려 저장하세요. 양쪽이 결과를 확정하면 사망·장비 삭제·강한 동맹의 대체 모델을 함께 반영합니다.')}</p>`,()=>can?resume(g):true,can?T('Open campaign play','캠페인 플레이 열기'):T('Close','닫기'));return true;
}};
window.MMCampaignPlay={open,restore,resume,canResume,viewGang,restorationError:()=>restoreError,activeFor:(roomId)=>current(active)&&active.room.id===roomId,returnToRoom:()=>active?returnToRoom(active):Promise.resolve(false),pending:()=>!!active?.pending};
})();
